const texto = '{"noticias":[{"titulo":"A"},{"titulo":"B"},{"titulo":"C"}]}';
const dados = JSON.parse(texto);
console.log(dados.noticias.length);

const texto = '{"noticias":[{"titulo":"Primeira","autor":"Italo"},{"titulo":"Segunda","autor":"Carolina"}]}';
const dados = JSON.parse(texto);
console.log(dados.noticias[1].autor);

const noticias = [
  { titulo: 'A', curtidas: 10 },
  { titulo: 'B', curtidas: 40 },
  { titulo: 'C', curtidas: 25 }
];
const filtradas = noticias.filter((noticia) => noticia.curtidas > 20);
console.log(filtradas.length);

const dados = {
  noticias: [
    { titulo: 'HTML' },
    { titulo: 'CSS' }
  ]
};
const lista = document.querySelector('#lista');

for (const noticia of dados.noticias) {
  const item = document.createElement('li');
  item.textContent = noticia.titulo;
  lista.appendChild(item);
}

console.log(lista.lastElementChild.textContent);
